-- Remove exactly what 000002 inserted. FK cascade on role_permissions means
-- deleting roles also removes their grants, but we delete grants explicitly
-- so this file's behavior doesn't depend on schema-level cascade choices.
DELETE FROM role_permissions
WHERE
    role_id IN (
        '00000000-0000-4000-8000-000000000001',
        '00000000-0000-4000-8000-000000000002',
        '00000000-0000-4000-8000-000000000003'
    );

DELETE FROM permissions
WHERE
    id IN (
        '00000000-0000-4000-8000-000000000101',
        '00000000-0000-4000-8000-000000000102',
        '00000000-0000-4000-8000-000000000103',
        '00000000-0000-4000-8000-000000000104',
        '00000000-0000-4000-8000-000000000105',
        '00000000-0000-4000-8000-000000000106',
        '00000000-0000-4000-8000-000000000107',
        '00000000-0000-4000-8000-000000000108',
        '00000000-0000-4000-8000-000000000109',
        '00000000-0000-4000-8000-000000000110',
        '00000000-0000-4000-8000-000000000111',
        '00000000-0000-4000-8000-000000000112'
    );

DELETE FROM roles
WHERE
    id IN (
        '00000000-0000-4000-8000-000000000001',
        '00000000-0000-4000-8000-000000000002',
        '00000000-0000-4000-8000-000000000003'
    );